// supabase/functions/restore-user-snapshot/index.ts
//
// C3 of the restore-performance overhaul — SINGLE-CALL cloud→client restore.
// Replaces the gated `restoreFromCloudForUser` ~27 client round-trips (web p95 97s)
// with ONE service_role read that returns the WHOLE per-user snapshot as a jsonb
// bundle the client writes to Hive in one pass.
//
// ── SECURITY (catastrophic — service_role BYPASSES RLS; this body is the ONLY guard) ──
//   • Auth via getUser(token) on a SERVICE_ROLE client (e8a1c3 contract). NEVER pass
//     the user JWT as the supabaseKey.
//   • v_uid is derived from the VALIDATED token and asserted NON-EMPTY + UUID-shaped
//     BEFORE any query is built — else 401 (H-4 / F3-F4 fail-open guard).
//   • NO client-supplied user-id param ever. EVERY table read is scoped to v_uid.
//     The three user_id-LESS tables are scoped via parent / dual-FK (live-verified):
//       - nutrition_log_items  → embedded under nutrition_logs (parent user_id)
//       - template_exercises   → embedded under workout_templates (parent user_id). The
//                                scheduled_workouts→template embed is NOT parent-scoped (the FK is
//                                caller-writable): paged_reads.ts scopeEmbed nulls a foreign owner (C13).
//       - referral_redemptions → dual-FK .or(referrer_id=v_uid, referee_id=v_uid)  (H-8:
//         v_uid is UUID-validated above, so the .or() string interpolation is injection-safe)
//     (workout_log_sets / workout_log_exercises DO carry user_id → scoped directly.)
//
// ── FAIL-CLOSED (H-2) ──
//   ANY single table-query error → throw → caught → 500 (non-200). NO per-table swallow
//   that returns a partial 200 (the legacy `_safeRestoreOp` swallow pattern is BANNED
//   here). The bundle emits EVERY table key UNCONDITIONALLY ([] / null when empty) plus a
//   top-level `schema_version` sentinel. The client treats an ABSENT key OR a missing
//   sentinel OR a non-200 as a FAULT → runs the verbatim legacy per-op restore this pass.
//
// ── SHAPE (H-1) ──
//   Each table value reproduces the legacy PostgREST response VERBATIM, including embed
//   nesting (nutrition_logs→nutrition_log_items(*); workout_templates→template_exercises(*);
//   scheduled_workouts→template:template_id(...template_exercises(*))) and the exact column
//   projections (coach_memory 10-col, freezes 5-col, referral_codes 3-col, redemptions
//   5-col, users 2-col), so the client `_restoreX` parsers hydrate UNCHANGED. The caps of the
//   NON-paged reads (limit 1/20/50/52/200/500) inherit today's behaviour verbatim (H-9); the
//   thirteen paged reads return EVERY row up to 50,000 per table. Column names are verbatim (H-11).
//   Unit 3b (OI-45 cross-device half, e6b9c4): freezes went 4-col -> 5-col to add
//   streak_progress_version — the legacy client-side _restoreFreezes select was updated in
//   the same commit, and this projection must keep matching it per H-1's own contract.
//
// ── PAGED READS (diagnose: restore-user-snapshot returns every row) ──
//   PostgREST clamps every response to `db-max-rows` (1000) with HTTP 200 and error === null, so a
//   single `.range(0, 49999)` silently returned at most 1000 rows. The thirteen bulk reads and the
//   coach window now live in `./paged_reads.ts` (testable without booting this module): every one
//   pages through `_shared/paged_fetch.ts` until an EMPTY page, applies its own `user_id` scope
//   (code-owned, never data), and orders by an explicit, unique-ended key. Beyond 50,000 rows in
//   one table, or beyond the per-request page budget across all of them, a read THROWS → the catch
//   below → 500 → the client's verbatim legacy restore (fail-closed).
//
// verify_jwt: true at deploy (user must be authenticated; gateway pre-check + getUser here).
// Plan: ~/.claude/plans/restore-single-call-c3.md.
// Live version: ask `list_edge_functions` (the deploy skill records each deploy in its diagnose
// doc); SyncService._singleCallKillSwitch defaults OFF, so the client attempts this path by
// default. Any edit to this file's response shape is a LIVE behavior change, not future-proofing —
// redeploy + smoke-test accordingly.
// closes-diagnose: (restore-perf single-call) — see docs/diagnoses on impl.

import { serve } from "https://deno.land/std@0.224.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";
import {
  createPageBudget,
  readCoachNewest,
  readPaged,
  rowCountLogLine,
  UUID_RE,
} from "./paged_reads.ts";

// Bump SCHEMA_VERSION whenever the bundle shape or table set changes — the client
// rejects a bundle whose schema_version it does not recognise (→ legacy fallback).
const SCHEMA_VERSION = 1;

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

const SUPABASE_URL = Deno.env.get("SUPABASE_URL");
const SERVICE_ROLE = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

if (!SUPABASE_URL || !SERVICE_ROLE) {
  console.error("[restore-user-snapshot] STARTUP FAILED — missing env vars:", {
    SUPABASE_URL: !!SUPABASE_URL,
    SERVICE_ROLE: !!SERVICE_ROLE,
  });
  throw new Error("[restore-user-snapshot] required env vars not set");
}

// The H-4 guard uses the ONE UUID_RE exported by paged_reads.ts (the readers re-validate with the
// same regexp): a token-derived user.id that is null / empty / non-UUID is rejected BEFORE any
// query, so a fail-open cross-user read is impossible.

function jsonError(status: number, error: string, requestId: string): Response {
  return new Response(JSON.stringify({ error, request_id: requestId }), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  const requestId = crypto.randomUUID().split("-")[0];

  if (req.method !== "POST") {
    return jsonError(405, "method_not_allowed", requestId);
  }

  try {
    // ── 1. AUTH — getUser(token) on a service_role client (e8a1c3) ───────────────
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return jsonError(401, "unauthenticated", requestId);
    }
    const token = authHeader.replace(/^Bearer\s+/i, "").trim();

    // Service-role client: bypasses RLS for the reads below, and re-validates the
    // caller's JWT. NEVER createClient(url, token) — that 401s every valid token.
    const db = createClient(SUPABASE_URL, SERVICE_ROLE, {
      auth: { persistSession: false, autoRefreshToken: false },
    });

    const { data: userData, error: userErr } = await db.auth.getUser(token);
    const vUid = userData?.user?.id;
    // H-4: bind the non-empty UUID invariant BEFORE building ANY query. Covers
    // getUser → {user:null, error:null} (deleted user / edge) and empty/non-UUID id.
    if (userErr || !vUid || typeof vUid !== "string" || !UUID_RE.test(vUid)) {
      return jsonError(401, "unauthenticated", requestId);
    }

    // ── 2. ASSEMBLE THE BUNDLE — fail-closed. Any q() throw → caught below → 500. ──
    // Every builder is scoped to vUid. `q` throws on a PostgREST error (NOT on a
    // legitimately-empty maybeSingle, which returns null) so a real read failure
    // aborts the WHOLE call rather than shipping a partial bundle.
    const q = async <T>(label: string, builder: PromiseLike<{ data: T; error: unknown }>): Promise<T> => {
      const { data, error } = await builder;
      if (error) {
        const msg = (error as { message?: string })?.message ?? String(error);
        throw new Error(`query_failed:${label}:${msg}`);
      }
      return data;
    };

    const tables: Record<string, unknown> = {};
    // ONE page budget per request, shared by every paged read (paged_reads.ts: TOTAL_PAGE_BUDGET).
    const budget = createPageBudget();

    // ── Step A — profile + lightweight ──────────────────────────────────────────
    tables["user_profile"] = await q(
      "user_profile",
      db.from("user_profile").select("*").eq("user_id", vUid).limit(1),
    );
    tables["users"] = await q(
      "users",
      db.from("users").select("full_name, email").eq("id", vUid).maybeSingle(),
    );
    tables["user_progress"] = await q(
      "user_progress",
      db.from("user_progress").select("*").eq("user_id", vUid).limit(1),
    );
    tables["user_preferences"] = await q(
      "user_preferences",
      db.from("user_preferences").select("*").eq("user_id", vUid).limit(1),
    );
    // OI-252 (stable ID rework): NO `is_active` filter -- the client now
    // needs BOTH live rows (to restore) AND deleted rows (to remove any
    // local copy + clean their schedules). `deleted_at` is on `*` already
    // (migration 145). Order live-first (nullsFirst) so a `.limit(500)`
    // clip loses stale delete evidence before it loses a live template --
    // a user is far likelier to approach 500 live templates than 500
    // deletes.
    tables["workout_templates"] = await q(
      "workout_templates",
      db.from("workout_templates")
        .select("*, template_exercises(*)")
        .eq("user_id", vUid)
        .order("deleted_at", { ascending: true, nullsFirst: true })
        .limit(500),
    );
    // workout_plan = the plan_json snapshot on user_progress (parser reads rows.first['plan_json']).
    tables["workout_plan"] = await q(
      "workout_plan",
      db.from("user_progress").select("plan_json").eq("user_id", vUid).limit(1),
    );
    tables["user_custom_exercises"] = await readPaged(db, vUid, "user_custom_exercises", budget);
    tables["user_custom_foods"] = await readPaged(db, vUid, "user_custom_foods", budget);

    // ── Step B — bulk history (paged: see the PAGED READS header; every call passes vUid) ──
    tables["workout_logs"] = await readPaged(db, vUid, "workout_logs", budget);
    tables["workout_log_exercises"] = await readPaged(db, vUid, "workout_log_exercises", budget);
    tables["workout_log_sets"] = await readPaged(db, vUid, "workout_log_sets", budget);
    tables["workout_schedule_completions"] = await readPaged(db, vUid, "workout_schedule_completions", budget);
    tables["weight_logs"] = await readPaged(db, vUid, "weight_logs", budget);
    tables["daily_steps"] = await readPaged(db, vUid, "daily_steps", budget);
    tables["nutrition_logs"] = await readPaged(db, vUid, "nutrition_logs", budget);
    tables["body_measurements"] = await readPaged(db, vUid, "body_measurements", budget);
    tables["water_logs"] = await readPaged(db, vUid, "water_logs", budget);
    tables["sleep_logs"] = await readPaged(db, vUid, "sleep_logs", budget);
    tables["streaks"] = await q(
      "streaks",
      db.from("streaks").select("*").eq("user_id", vUid)
        .order("week_start", { ascending: false }).limit(52),
    );
    // OI-252: `deleted_at` is in the embed so the client can tell a deleted template's schedule
    // day apart from a merely-missing embed. The embed is owner-scoped inside readPaged (a
    // foreign template becomes null: Hermes C13).
    tables["scheduled_workouts"] = await readPaged(db, vUid, "scheduled_workouts", budget);
    tables["user_saved_meals"] = await q(
      "user_saved_meals",
      db.from("user_saved_meals").select("*").eq("user_id", vUid).limit(500),
    );
    // The NEWEST 1000 coach interactions, ascending (bundle shape unchanged). It used to keep
    // the OLDEST 1000 once a user passed 1000 rows.
    tables["ai_coach_interactions"] = await readCoachNewest(db, vUid);
    tables["coach_memory"] = await q(
      "coach_memory",
      // 10-column projection ONLY (H-12) — never SELECT * (keeps server-only risk
      // scores / private fields off the wire). Mirrors sync_coach.dart:222-230.
      db.from("coach_memory")
        .select(
          "committed_at, committed_to_lt_cdr, induction_completed_at, why_now, definition_of_winning, known_injuries, typical_wake_time, preferred_workout_time, body_part_priorities, coach_notes",
        )
        .eq("user_id", vUid)
        .maybeSingle(),
    );

    // ── Step C — restore-completeness surfaces ────────────────────────────────────
    tables["freezes"] = await q(
      "freezes",
      db.from("user_progress")
        .select(
          "streak_freezes_available, streak_freezes_used_dates, streak_freezes_last_refill, streak_freezes_first_pro_grant_done, streak_progress_version",
        )
        .eq("user_id", vUid)
        .maybeSingle(),
    );
    tables["notifications_inbox"] = await q(
      "notifications_inbox",
      db.from("notifications_inbox").select("*").eq("user_id", vUid)
        .order("created_at", { ascending: false }).limit(200),
    );
    tables["saved_diet_plan"] = await q(
      "saved_diet_plan",
      db.from("saved_diet_plans").select("plan_json").eq("user_id", vUid).maybeSingle(),
    );
    tables["rank_promotions"] = await q(
      "rank_promotions",
      db.from("rank_promotions").select("*").eq("user_id", vUid)
        .order("achieved_at", { ascending: false }).limit(20),
    );
    tables["referral_codes"] = await q(
      "referral_codes",
      db.from("referral_codes").select("code, expires_at, created_at").eq("user_id", vUid)
        .gt("expires_at", new Date().toISOString())
        .order("created_at", { ascending: false }).limit(1).maybeSingle(),
    );
    tables["referral_redemptions"] = await q(
      "referral_redemptions",
      // Dual-FK self-scope (H-8). vUid is UUID-validated → .or() interpolation is safe.
      db.from("referral_redemptions")
        .select("code, referrer_id, referee_id, days_granted_each, created_at")
        .or(`referrer_id.eq.${vUid},referee_id.eq.${vUid}`)
        .order("created_at", { ascending: false }).limit(50),
    );

    // Table names and row COUNTS only (never a row value): the live behaviour of the paged reads
    // is read from the function logs, since no user token is available to smoke-test with.
    console.log(rowCountLogLine(requestId, tables));

    // ── 3. RETURN — all keys present + sentinel. (subscriptions is NOT in the bundle;
    //     the client keeps the separate refreshFromSupabase() call — H-3.) ──────────
    const bundle = {
      schema_version: SCHEMA_VERSION,
      generated_at: new Date().toISOString(),
      tables,
    };
    return new Response(JSON.stringify(bundle), {
      status: 200,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (e) {
    // FAIL-CLOSED: any read error → 500 (non-200). The client falls back to the
    // verbatim legacy per-op restore this pass. No PII / no stack in the body.
    console.error(`[restore-user-snapshot] request_id=${requestId}`, e);
    return jsonError(500, "restore_snapshot_failed", requestId);
  }
});

// supabase/functions/restore-user-snapshot/paged_reads.ts
//
// The paged reads of `restore-user-snapshot`, extracted so they can be tested without booting
// `index.ts` (which reads env and calls `serve()` at module scope).
//
// ── Why this exists (diagnose: restore-user-snapshot returns every row) ──
//   PostgREST caps every response at `db-max-rows` (1000 on this project) with HTTP 200 and
//   `error === null` (see `_shared/paged_fetch.ts`). Nine reads in `index.ts` used ONE
//   `.range(0, 49999)`, `scheduled_workouts` used `.range(0, 999)`, `workout_schedule_completions`
//   had no limit and the two `user_custom_*` reads were bare selects, so every one silently
//   returned at most 1000 rows; `ai_coach_interactions` kept the OLDEST 1000. The legacy client
//   restore pages; the single-call path did not. Every read here now pages until an empty page
//   arrives, through `fetchAllPages`.
//
// ── SECURITY (catastrophic — service_role BYPASSES RLS; the function body is the ONLY guard) ──
//   • `readPaged` / `readCoachNewest` apply `.eq("user_id", vUid)` THEMSELVES, FIRST, on every
//     page. The scope is code-owned, NEVER manifest data, so a manifest entry cannot forget it.
//   • `vUid` is re-validated here (non-empty, UUID-shaped) before any query is built. `index.ts`
//     validates the token-derived id first, with the SAME exported `UUID_RE`; this is defence in
//     depth, not a replacement.
//   • ONE request may issue at most `TOTAL_PAGE_BUDGET` page requests across all thirteen reads (a
//     shared `PageBudget`, REQUIRED by `readPaged`): a user can write unbounded rows of their own
//     (RLS only pins `user_id`), and the function holds every row in memory. Beyond the budget a
//     read throws, which `index.ts` turns into the 500 that sends the client down its own legacy
//     per-user-JWT restore (fail-closed, never a partial bundle).
//   • An unknown table name THROWS (never returns `[]`), so a typo is a loud 500, not a silent
//     empty section.
//   • The `scheduled_workouts.template` embed is scoped only by a foreign key and
//     `workout_templates` is not filtered by user, so a row pointing at ANOTHER user's template
//     would leak that template's name and exercises (Hermes C13, open since 2026-07-30). The
//     embed selects the template's `user_id`; a foreign embed is replaced with `null`, and an
//     owned one has `user_id` stripped again so the bundle keeps its legacy shape.
//
// This module imports only `../_shared/paged_fetch.ts`: never `index.ts`, never a bare
// supabase-js specifier (the deploy payload ships no import map).

import { fetchAllPages, type OrderKey } from "../_shared/paged_fetch.ts";

// Full-history restore window — UNCHANGED from the legacy client. ONE owner (index.ts imports it).
export const SINCE = "2020-01-01T00:00:00Z";
// '2020-01-01' for date-typed columns (daily_steps / water_logs / scheduled_workouts).
export const SINCE_DATE = SINCE.substring(0, 10);

// 50 full pages (50,000 rows = the legacy client's `_fetchAllRows` ceiling) plus the one confirming
// EMPTY page. `fetchAllPages` THROWS beyond it, which `index.ts` turns into the same 500 envelope as
// any other read failure, which the client treats as "fall back to the legacy path".
export const MAX_PAGES = 51;
export const PAGE_SIZE = 1000;

// The coach read keeps the newest rows: the legacy client's default order is descending, so a
// `.limit(1000)` there already keeps the newest 1000; supabase-js defaults to ASCENDING, which kept
// the OLDEST 1000 once a user passed 1000 rows.
export const COACH_LIMIT = 1000;

// RFC-4122 UUID shape, anchored (no `m` flag: a trailing newline fails). The ONE definition:
// `index.ts` imports it for its own pre-query check, so the two guards cannot drift apart.
export const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// A request's page budget. A read costs ONE request for an empty table, otherwise one per 1000 rows
// plus the confirming empty page: 13 x 2 = 26 for a user with a few hundred rows per table, 13 x 4 =
// 52 at 3,000 rows each. 120 covers about 100,000 rows in total. One table at the legacy 50,000-row
// ceiling costs 51, so two of them (102) fit only if at most 7 of the other eleven tables hold any
// rows. Past the budget a read throws and the client's own legacy restore runs. The budget bounds
// REQUESTS, not bytes: a worker killed for memory also answers non-200 (the same fallback).
export const TOTAL_PAGE_BUDGET = 120;

export interface PageBudget {
  /** Page requests this request may still issue across ALL paged reads. */
  remaining: number;
}

/** A fresh budget: ONE per request (never module state: requests run concurrently). */
export function createPageBudget(): PageBudget {
  return { remaining: TOTAL_PAGE_BUDGET };
}

// deno-lint-ignore no-explicit-any
export type DbLike = { from(table: string): any };

export interface PagedReadSpec {
  /** The EXACT select string of the read this replaces (embeds included). */
  select: string;
  /** Optional lower bound, `gte(column, value)`. */
  gte?: { column: string; value: string };
  /**
   * ORDER BY terms, each with an EXPLICIT direction (supabase-js defaults to ascending, the Dart
   * client to descending; nothing here relies on a default). The LAST term must be unique (`id`).
   */
  order: OrderKey[];
  /** A to-one embed whose owner must equal the caller (see SECURITY above). */
  embedScope?: { path: string; column: string };
}

/**
 * The thirteen paged reads, in bundle order. Every entry reproduces its legacy select string,
 * filter column and primary sort column; the added terms (`created_at`, `id`) are tie-breakers so
 * two page requests can never skip or duplicate a row that shares the primary sort key.
 */
export const PAGED_READS: Record<string, PagedReadSpec> = {
  // The legacy reads had NO order (physical order, roughly insertion order). The client keeps the
  // FIRST row per lower-cased name, so `created_at` comes before the page-seam-only `id`.
  user_custom_exercises: {
    select: "*",
    order: [
      { column: "created_at", ascending: true },
      { column: "id", ascending: true },
    ],
  },
  user_custom_foods: {
    select: "*",
    order: [
      { column: "created_at", ascending: true },
      { column: "id", ascending: true },
    ],
  },
  workout_logs: {
    select: "*",
    gte: { column: "created_at", value: SINCE },
    order: [
      { column: "created_at", ascending: true },
      { column: "id", ascending: true },
    ],
  },
  workout_log_exercises: {
    select: "*",
    gte: { column: "completed_at", value: SINCE },
    // created_at is a fair insertion-order proxy (one single-row upsert per row sets it
    // server-side); `id` is a random uuid and only guarantees page-seam stability.
    order: [
      { column: "completed_at", ascending: true },
      { column: "created_at", ascending: true },
      { column: "id", ascending: true },
    ],
  },
  workout_log_sets: {
    select: "*",
    gte: { column: "completed_at", value: SINCE },
    order: [
      { column: "completed_at", ascending: true },
      { column: "created_at", ascending: true },
      { column: "id", ascending: true },
    ],
  },
  workout_schedule_completions: {
    select: "*",
    // Filters `completed_at` but sorts `scheduled_date`: preserved exactly as the legacy read had it.
    gte: { column: "completed_at", value: SINCE },
    order: [
      { column: "scheduled_date", ascending: true },
      { column: "id", ascending: true },
    ],
  },
  weight_logs: {
    select: "*",
    gte: { column: "created_at", value: SINCE },
    order: [
      { column: "created_at", ascending: true },
      { column: "id", ascending: true },
    ],
  },
  daily_steps: {
    select: "*",
    gte: { column: "date", value: SINCE_DATE },
    order: [
      { column: "date", ascending: true },
      { column: "id", ascending: true },
    ],
  },
  nutrition_logs: {
    select: "*, nutrition_log_items(*)",
    gte: { column: "created_at", value: SINCE },
    order: [
      { column: "created_at", ascending: true },
      { column: "id", ascending: true },
    ],
  },
  body_measurements: {
    select: "*",
    gte: { column: "created_at", value: SINCE },
    order: [
      { column: "created_at", ascending: true },
      { column: "id", ascending: true },
    ],
  },
  water_logs: {
    select: "*",
    gte: { column: "date", value: SINCE_DATE },
    order: [
      { column: "date", ascending: true },
      { column: "id", ascending: true },
    ],
  },
  sleep_logs: {
    select: "*",
    gte: { column: "created_at", value: SINCE },
    order: [
      { column: "created_at", ascending: true },
      { column: "id", ascending: true },
    ],
  },
  // OI-252: `deleted_at` is in the embed so the client can tell a deleted template's schedule day
  // apart from a merely-missing embed. `user_id` is added to the embed ONLY to scope it (stripped
  // again by readPaged); every other column is the legacy projection.
  scheduled_workouts: {
    select:
      "*, template:template_id(id, name, workout_type, deleted_at, user_id, template_exercises(*))",
    gte: { column: "scheduled_date", value: SINCE_DATE },
    order: [
      { column: "scheduled_date", ascending: true },
      { column: "id", ascending: true },
    ],
    embedScope: { path: "template", column: "user_id" },
  },
};

/** The bundle keys read through this module, in the order `index.ts` assigns them. */
export const PAGED_READ_NAMES: string[] = Object.keys(PAGED_READS);
export const COACH_TABLE = "ai_coach_interactions";

function assertUserId(vUid: unknown): asserts vUid is string {
  if (typeof vUid !== "string" || !UUID_RE.test(vUid)) {
    // Never build a query for an unvalidated id: a null/empty id must not become an unscoped read.
    throw new Error("paged_reads: user id is not a validated uuid");
  }
}

/**
 * Scopes a to-one embed to the caller. `row[path]` is the embedded object (or null/absent).
 * A foreign owner yields `null`; an owned embed loses its `user_id` so the shape is the legacy one.
 * Anything that is not a plain object (an array, a string, a number) is NOT trusted: it becomes
 * `null`, never passed through. The owner comparison is case-insensitive (a uuid is the same uuid
 * in either case, and `UUID_RE` accepts both), so an owned template is never nulled by casing.
 */
export function scopeEmbed(
  rows: Record<string, unknown>[],
  vUid: string,
  scope: { path: string; column: string },
): Record<string, unknown>[] {
  const me = vUid.toLowerCase();
  return rows.map((row) => {
    const embed = row[scope.path];
    if (embed === null || embed === undefined) return row;
    // Explicit, though the owner check below would also null these shapes (defence in depth).
    if (typeof embed !== "object" || Array.isArray(embed)) {
      return { ...row, [scope.path]: null };
    }
    const e = embed as Record<string, unknown>;
    const owner = e[scope.column];
    if (typeof owner !== "string" || owner.toLowerCase() !== me) {
      return { ...row, [scope.path]: null };
    }
    const { [scope.column]: _owner, ...rest } = e;
    return { ...row, [scope.path]: rest };
  });
}

/**
 * Reads EVERY row of one paged table for `vUid`. Throws on any page error (no partial result), on
 * an unknown name, on an unvalidated user id, beyond `MAX_PAGES` pages for this table, and when the
 * REQUEST's shared `budget` is spent (the budget is required: a call that forgot it would be
 * unbounded). Each page request taken is charged to the budget, success or failure.
 */
export async function readPaged(
  db: DbLike,
  vUid: string,
  name: string,
  budget: PageBudget,
): Promise<unknown[]> {
  assertUserId(vUid);
  if (!Object.hasOwn(PAGED_READS, name)) {
    throw new Error(`paged_reads: unknown paged read '${name}'`);
  }
  if (!budget || !Number.isInteger(budget.remaining) || budget.remaining < 1) {
    throw new Error(`paged_reads: page budget exhausted before '${name}'`);
  }
  const spec = PAGED_READS[name];

  // This table may take at most what the request has left, capped at the per-table ceiling.
  const maxPages = Math.min(MAX_PAGES, budget.remaining);
  let pagesTaken = 0;
  try {
    const rows = await fetchAllPages<Record<string, unknown>>(
      () => {
        pagesTaken++;
        // The user scope is applied HERE, first, on every page: fetchAllPages calls this factory
        // once per page, so no page can ever be unscoped.
        let q = db.from(name).select(spec.select).eq("user_id", vUid);
        if (spec.gte) q = q.gte(spec.gte.column, spec.gte.value);
        return q;
      },
      {
        orderBy: spec.order,
        pageSize: PAGE_SIZE,
        maxPages,
        label: `restore-user-snapshot ${name}`,
      },
    );
    return spec.embedScope ? scopeEmbed(rows, vUid, spec.embedScope) : rows;
  } catch (e) {
    // fetchAllPages words a maxPages throw as a SORT-KEY problem ("an unstable sort key can loop
    // forever"). When the request budget, not the per-table ceiling, was the limit, say so: an
    // operator reading the log must not chase a sort key that is fine.
    if (maxPages < MAX_PAGES && e instanceof Error && e.message.includes("exceeded maxPages")) {
      throw new Error(
        `paged_reads: page budget exhausted at '${name}' (this read was allowed ${maxPages} pages)`,
      );
    }
    throw e;
  } finally {
    budget.remaining -= pagesTaken;
  }
}

/**
 * The newest `COACH_LIMIT` coach interactions for `vUid`, returned in ASCENDING `created_at` order
 * (the bundle's legacy shape; the client keys each row by `created_at`, so order is not relied on).
 * Not paged: it is a bounded recency window, so it bypasses `fetchAllPages` — and therefore owns
 * its own throw-on-error and its own user scope.
 */
export async function readCoachNewest(
  db: DbLike,
  vUid: string,
): Promise<unknown[]> {
  assertUserId(vUid);
  const { data, error } = await db
    .from(COACH_TABLE)
    .select("*")
    .eq("user_id", vUid)
    .gte("created_at", SINCE)
    .order("created_at", { ascending: false })
    .order("id", { ascending: false })
    .limit(COACH_LIMIT);
  if (error) {
    const msg = (error as { message?: string })?.message ?? String(error);
    throw new Error(`query_failed:${COACH_TABLE}:${msg}`);
  }
  return [...((data ?? []) as unknown[])].reverse();
}

/**
 * The per-request log line: table names and row COUNTS only — never a row value — so the live
 * behaviour can be read from the function logs without a user token.
 */
export function rowCountLogLine(
  requestId: string,
  tables: Record<string, unknown>,
): string {
  const names = [...PAGED_READ_NAMES, COACH_TABLE];
  const counts = names.map((n) => {
    const v = tables[n];
    return `${n}=${Array.isArray(v) ? v.length : "n/a"}`;
  });
  return `[restore-user-snapshot] request_id=${requestId} rows ${counts.join(" ")}`;
}

/**
 * paged_fetch — bounded reads for cron Edge Functions (OI-79).
 *
 * ## The bug this exists to prevent
 *
 * PostgREST caps every response at `db-max-rows` (1000 on this project) and
 * **supabase-js gives you no way to notice**. Measured live 2026-08-01 against
 * `dedsavbjuwgarrhphgnl`, `food_database` (1431 rows):
 *
 * | request                                   | status | Content-Range | rows |
 * |-------------------------------------------|--------|---------------|------|
 * | `?select=id` (what `.select()` sends)      | 200 OK | `0-999/*`     | 1000 |
 * | `Range: 0-1499`                            | 200 OK | `0-999/*`     | 1000 |
 * | `Range: 1000-1999`                         | 200 OK | `1000-1430/*` |  431 |
 * | `Prefer: count=exact`                      | 206    | `0-999/1431`  | 1000 |
 *
 * Three things follow, and each one is load-bearing:
 *
 * 1. **It is a 200, not a 206.** OI-79 was filed saying truncation shows up as
 *    `206 Partial Content`. That is only true when the caller asks for a count,
 *    and no cron function here does. In the shape our code actually sends, the
 *    response is a plain `200 OK` with a short body and `error === null`. There
 *    is no status, no error, and no total (`/*`) to compare against — a
 *    truncated read is *byte-for-byte indistinguishable* from a small one. The
 *    only signal is the row count, and it is AMBIGUOUS: a page shorter than
 *    `pageSize` means either end-of-data or a server cap below `pageSize`.
 *    That is why the loop terminates on an EMPTY page, never a short one.
 * 2. **`.range()` cannot raise the cap.** Asking for 0-1499 still yields 1000.
 *    So `pageSize` MUST be <= the cap; a larger value does not fetch more, it
 *    silently breaks the loop (you ask for 1500, get 1000, read that as a short
 *    page, and stop early — dropping every row after the first page).
 * 3. **Paging past the cap works.** Offset 1000-1999 returns the remainder.
 *    A `.range()` loop is therefore a real fix, not a workaround.
 *
 * ## Why `orderBy` is required and has no default
 *
 * Postgres guarantees no row order without an `ORDER BY`, and PostgREST adds
 * none. Two `.range()` calls against an unordered relation may return
 * overlapping or disjoint slices, so a paginated loop without a stable sort key
 * can **duplicate or skip rows** — silently, and only under load. Three loops in
 * this repo shipped that way (`morning-alert`, `weekly-recap-ready`,
 * `weekly-recalc`); `i-see-you-callout` got it right with
 * `.order("id", { ascending: true })`. Making `orderBy` a required parameter
 * with no default is how that mistake becomes unconstructible here.
 *
 * Pick a key that is **unique and immutable** — a primary key. A non-unique key
 * (`date`, `status`) does not fully order the rows, so ties can shuffle between
 * page requests and reintroduce the same skip/duplicate bug.
 *
 * ## RPCs
 *
 * `.order()` / `.range()` are accepted on `/rpc/` set-returning functions, so
 * both helpers work with `() => supabase.rpc(...)`. Whether `db-max-rows` also
 * caps RPC responses could not be settled from here: the only anon-executable
 * set-returning functions on this project are not `SECURITY DEFINER`, so RLS
 * returns 0 rows to `anon` and the probe is inconclusive. It does not change
 * anything — these helpers page unconditionally, which is correct either way
 * (if the cap does not apply, the loop simply ends on the first empty page).
 *
 * @see docs/audit/open_issues.md OI-79
 */

// deno-lint-ignore-file no-explicit-any

/**
 * PostgREST's server-side `db-max-rows` for this project, confirmed live
 * (table above). A response can never exceed this many rows regardless of the
 * requested `Range`.
 */
export const POSTGREST_MAX_ROWS = 1000;

/** Default page size. Sits at the cap: the largest value that is still safe. */
export const DEFAULT_PAGE_SIZE = 1000;

/**
 * Default `.in()` chunk size. Bounds the **request URL**, which is a different
 * constraint from `pageSize` (which bounds the *response*). A uuid costs ~37
 * bytes in `in.(...)`, so 100 ids is ~3.7KB and stays clear of the ~4-8KB URL
 * limits proxies impose. Matches the existing `BATCH_SIZE = 100` precedent in
 * `evaluate-rank-promotions`.
 */
export const DEFAULT_CHUNK_SIZE = 100;

/**
 * Runaway guard. At the default page size this permits 10M rows, far beyond any
 * legitimate cron scan — it exists to turn "PostgREST keeps returning full
 * pages forever" (an unstable sort key, a clock-skewed filter) into a loud
 * failure instead of an Edge Function that runs until the platform kills it.
 */
export const DEFAULT_MAX_PAGES = 10_000;

/** Minimal structural shape we need from a supabase-js query builder. */
interface RangeableBuilder {
  order(column: string, opts: { ascending: boolean }): RangeableBuilder;
  range(from: number, to: number): PromiseLike<{ data: unknown; error: unknown }>;
}

/** One ORDER BY term. */
export interface OrderKey {
  column: string;
  ascending?: boolean;
}

export interface PagedFetchOptions {
  /**
   * REQUIRED. Sort key — must be unique and immutable (a primary key). See the
   * header note on why this has no default.
   *
   * Pass an array to sort by several columns, e.g. to page a "most recent row
   * per user" read while preserving its ordering semantics:
   * `[{ column: "snapshot_date", ascending: false }, { column: "id" }]`.
   * The **last** term must be unique — the earlier ones can tie, and ties
   * without a unique tiebreaker are exactly the unstable-page bug.
   */
  orderBy: string | OrderKey[];
  /**
   * Sort direction for the single-column form. Ignored when `orderBy` is an
   * array (each term carries its own).
   */
  ascending?: boolean;
  /** Rows per request. MUST be <= {@link POSTGREST_MAX_ROWS}; see header note 2. */
  pageSize?: number;
  /** Runaway guard, see {@link DEFAULT_MAX_PAGES}. */
  maxPages?: number;
  /** Prefix for the saturation log line. Defaults to "paged_fetch". */
  label?: string;
}

/** Normalises the `orderBy` union into a non-empty list of ORDER BY terms. */
function orderKeys(opts: PagedFetchOptions): OrderKey[] {
  const bad = () => {
    throw new Error(
      "paged_fetch: `orderBy` is required and must be a non-empty column name " +
        "(or a non-empty array of them). A .range() loop without a stable sort " +
        "key can skip or duplicate rows (OI-79).",
    );
  };

  if (typeof opts.orderBy === "string") {
    if (!opts.orderBy.trim()) bad();
    return [{ column: opts.orderBy, ascending: opts.ascending ?? true }];
  }
  if (!Array.isArray(opts.orderBy) || opts.orderBy.length === 0) bad();
  const keys = (opts.orderBy as OrderKey[]).map((k) => {
    if (!k || typeof k.column !== "string" || !k.column.trim()) bad();
    return { column: k.column, ascending: k.ascending ?? true };
  });
  return keys;
}

function validate(opts: PagedFetchOptions): { pageSize: number; maxPages: number } {
  orderKeys(opts); // throws when the sort key is missing or malformed
  const pageSize = opts.pageSize ?? DEFAULT_PAGE_SIZE;
  if (!Number.isInteger(pageSize) || pageSize < 1) {
    throw new Error(`paged_fetch: pageSize must be a positive integer, got ${pageSize}`);
  }
  if (pageSize > POSTGREST_MAX_ROWS) {
    throw new Error(
      `paged_fetch: pageSize ${pageSize} exceeds PostgREST's db-max-rows ` +
        `(${POSTGREST_MAX_ROWS}). A larger page cannot fetch more rows — the server ` +
        `silently clamps it — so every page costs a full round-trip for at most ` +
        `${POSTGREST_MAX_ROWS} rows while the arithmetic implies more. The loop itself is ` +
        `SAFE at any cap (it advances by rows received and stops only on an empty page), ` +
        `so this is a wrong-configuration guard, not a correctness one. ` +
        `Use a pageSize <= ${POSTGREST_MAX_ROWS} (OI-79).`,
    );
  }
  const maxPages = opts.maxPages ?? DEFAULT_MAX_PAGES;
  if (!Number.isInteger(maxPages) || maxPages < 1) {
    throw new Error(`paged_fetch: maxPages must be a positive integer, got ${maxPages}`);
  }
  return { pageSize, maxPages };
}

/**
 * Reads **every** row matching a query, paging until an EMPTY page arrives.
 *
 * `makeQuery` must return a fresh builder each call — supabase-js builders are
 * single-use thenables, so reusing one across pages does not work. Apply your
 * filters there and let this apply `.order()` and `.range()`:
 *
 * ```ts
 * const rows = await fetchAllPages<{ user_id: string }>(
 *   () => supabase.from("coach_memory").select("user_id").gte("dropout_risk_score", 0.5),
 *   { orderBy: "user_id", label: "re-engagement path A" },
 * );
 * ```
 *
 * Throws on the first page error rather than returning partial rows. That is
 * deliberate: silently proceeding with an incomplete candidate set is the exact
 * failure this module exists to prevent, and a cron tick that cannot read its
 * inputs should fail loudly and retry on the next tick.
 */
export async function fetchAllPages<T>(
  makeQuery: () => unknown,
  opts: PagedFetchOptions,
): Promise<T[]> {
  const { pageSize, maxPages } = validate(opts);
  const keys = orderKeys(opts);
  const label = opts.label ?? "paged_fetch";
  const keyDesc = keys.map((k) => `${k.column}${k.ascending ? "" : " desc"}`).join(", ");

  const all: T[] = [];

  for (let page = 0; ; page++) {
    if (page >= maxPages) {
      throw new Error(
        `paged_fetch[${label}]: exceeded maxPages=${maxPages} (${all.length} rows read). ` +
          `Every page came back full — check that orderBy='${keyDesc}' ends in a unique, ` +
          `immutable column; an unstable sort key can loop forever.`,
      );
    }

    // Offset by rows ACTUALLY received, never by `page * pageSize`. The two
    // agree only while the server serves full pages, and `db-max-rows` is a
    // dashboard setting (Settings -> API -> Max rows), not a platform
    // invariant. Lower it to 500 and the old arithmetic broke completely:
    // page 0 asked 0-999, got 500, and `500 < pageSize` read as end-of-data —
    // so every one of the reads this module was written to fix would silently
    // return 500 rows with error === null. Advancing by `all.length` makes the
    // loop correct for ANY server cap without having to know what it is.
    const from = all.length;
    const to = from + pageSize - 1;

    let q = makeQuery() as RangeableBuilder;
    for (const k of keys) q = q.order(k.column, { ascending: k.ascending ?? true });
    const builder = q.range(from, to);

    const { data, error } = await builder;
    if (error) {
      throw new Error(
        `paged_fetch[${label}]: page ${page} (rows ${from}-${to}) failed: ` +
          `${(error as { message?: string } | null)?.message ?? String(error)}`,
      );
    }

    const rows = (data ?? []) as T[];
    all.push(...rows);

    // Only an EMPTY page proves end-of-data. A SHORT page does not: it is
    // equally the signature of a server cap below `pageSize` (see the offset
    // note above), and treating it as "done" is exactly the silent truncation
    // this module exists to prevent.
    //
    // COST, stated honestly. For `fetchAllPages` this is one extra round-trip
    // per read. For `fetchAllByIds` it is one extra per CHUNK, and with
    // DEFAULT_CHUNK_SIZE = 100 a chunk essentially never fills a 1000-row
    // page — so the confirming request lands on ~every chunk, not on a rare
    // boundary. 12 chunked call sites; at ~10k PRO users protein-gap-alert
    // goes from roughly 300 to 600 sequential round-trips per tick. Accepted
    // deliberately: these are daily cron jobs where wall-clock is cheap, and
    // the alternative is a read that silently returns half its rows with
    // error === null. If round-trips ever become the constraint, learn the
    // server's real page size once per process instead. (Corrected after
    // round-2 review — the earlier note claimed "the same one the
    // exact-multiple case already paid", true of fetchAllPages and NOT of the
    // chunked path that dominates.)
    if (rows.length === 0) break;
  }

  return all;
}

/**
 * Reads every row for a set of ids, chunking the `.in()` list **and** paging
 * within each chunk.
 *
 * Chunking alone is not enough, and that distinction is the whole point of this
 * function. `evaluate-rank-promotions` already had a `fetchInChunks` helper that
 * split `userIds` into batches of 100 — but a chunk bounds the *request*, not
 * the *response*. One 100-id chunk against a table holding N rows per user
 * returns 100xN rows, so it truncates at 10 rows/user no matter how small the
 * chunk is. This pages inside each chunk, which bounds both.
 *
 * ```ts
 * const logs = await fetchAllByIds<{ user_id: string }>(
 *   (chunk) => supabase.from("nutrition_logs")
 *                      .select("user_id, total_protein")
 *                      .eq("date", todayIST)
 *                      .in("user_id", chunk),
 *   proUserIds,
 *   { orderBy: "id", label: "protein-gap-alert nutrition" },
 * );
 * ```
 */
export async function fetchAllByIds<T>(
  makeQuery: (idChunk: string[]) => unknown,
  ids: string[],
  opts: PagedFetchOptions & { chunkSize?: number },
): Promise<T[]> {
  validate(opts);

  const chunkSize = opts.chunkSize ?? DEFAULT_CHUNK_SIZE;
  if (!Number.isInteger(chunkSize) || chunkSize < 1) {
    throw new Error(`paged_fetch: chunkSize must be a positive integer, got ${chunkSize}`);
  }

  if (ids.length === 0) return [];

  const all: T[] = [];
  for (let i = 0; i < ids.length; i += chunkSize) {
    const chunk = ids.slice(i, i + chunkSize);
    const rows = await fetchAllPages<T>(() => makeQuery(chunk), {
      ...opts,
      label: `${opts.label ?? "paged_fetch"} chunk@${i}`,
    });
    all.push(...rows);
  }
  return all;
}
